def run(question, search_results, fetch_title, fetch_text):
    q = (question or '').strip()
    ql = q.lower()
    meeting_words = [
        'meeting', 'call', 'prep', 'prepare', 'agenda', 'minutes', 'note', 'notes',
        'interview', 'standup', '1:1', 'one-on-one', 'one on one', 'sync', 'demo',
        'workshop', 'briefing', 'presentation', 'sales', 'client', 'stakeholder',
        'team', 'status', 'kickoff', 'follow-up', 'follow up'
    ]
    allowed = any(w in ql for w in meeting_words)

    snippets = []
    if isinstance(search_results, list):
        for r in search_results[:5]:
            if isinstance(r, dict):
                title = (r.get('title') or '').strip()
                content = (r.get('content') or '').strip()
                url = (r.get('url') or '').strip()
                bit = ' '.join(x for x in [title, content[:220], url] if x)
                if bit:
                    snippets.append(bit[:400])
    if isinstance(fetch_title, str) and fetch_title.strip():
        snippets.append(fetch_title.strip()[:200])
    if isinstance(fetch_text, str) and fetch_text.strip():
        t = ' '.join(fetch_text.split())
        if t:
            snippets.append(t[:600])

    facts = []
    seen = set()
    for s in snippets:
        s2 = s.strip()
        key = s2.lower()
        if s2 and key not in seen:
            seen.add(key)
            facts.append(s2)
        if len(facts) >= 6:
            break

    if not allowed:
        facts = []

    facts_text = '\n'.join(f'- {f}' for f in facts) if facts else 'No useful meeting facts extracted.'
    return {
        'allowed': allowed,
        'facts': facts,
        'facts_text': facts_text
    }
